import json
with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract_packages(data):
    result = {}
    for project in data.get('projects', []):
        pname = project['path'].split('/')[-1]
        result[pname] = {}
        for fw in project.get('frameworks', []):
            tfm = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                key = (pkg['id'], tfm)
                result[pname][key] = pkg['resolvedVersion']
    return result

b = extract_packages(baseline)
a = extract_packages(after)

print('=== CHANGES ===')
changes = False
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for key in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(key)
        av = ap.get(key)
        if bv != av:
            changes = True
            print(f'  {proj} | {key[0]} ({key[1]}): {bv} -> {av}')

if not changes:
    print('  No version changes detected')

print()
print('=== SUMMARY ===')
total_pkgs = set()
for proj in a:
    for key in a[proj]:
        total_pkgs.add(key[0])
print(f'Total unique packages centralized: {len(total_pkgs)}')
print(f'Projects converted: {len(a)}')
"
